SELECT N.ID, N.NOME, N.MOTIVO, N.CONFERIDO, N.CONF_NOTA, N.SUBTIPO, (SELECT COUNT(DISTINCT L.VIDEO_ID) FROM LIVROS_INDICADOS L JOIN VIDEOS V ON V.ID = L.VIDEO_ID WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}})) VIDEOS, (SELECT MIN(L.ID) FROM LIVROS_INDICADOS L JOIN VIDEOS V ON V.ID = L.VIDEO_ID WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}})) INDICADO_ID, S.STATUS FROM LIVROS_NOMES N LEFT JOIN ITENS_STATUS S ON S.TIPO = N.ESTADO AND S.NOME COLLATE utf8mb4_0900_ai_ci = N.NOME WHERE N.ESTADO = '{{estado}}' AND ({{canalId}} = 0 OR EXISTS (SELECT 1 FROM LIVROS_INDICADOS LX JOIN VIDEOS VX ON VX.ID = LX.VIDEO_ID WHERE LX.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME AND VX.CANAL_ID = {{canalId}})) AND ('{{busca}}' = '' OR N.NOME LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{status}}' = '' OR ('{{status}}' = 'NENHUM' AND COALESCE(S.STATUS, '') = '') OR S.STATUS = '{{status}}') AND ('{{conf}}' = '' OR COALESCE(N.CONFERIDO, 'NOVO') = '{{conf}}') AND ('{{subtipo}}' = '' OR ('{{subtipo}}' = 'nenhum' AND N.SUBTIPO IS NULL) OR N.SUBTIPO = '{{subtipo}}') AND ('{{fav}}' = '' OR EXISTS (SELECT 1 FROM ITENS_FAVORITOS FV WHERE FV.TIPO = N.ESTADO AND FV.NOME COLLATE utf8mb4_0900_ai_ci = N.NOME)) ORDER BY (N.CONFERIDO = 'DUVIDA') DESC, IF('{{ordem}}' = 'az', 0, VIDEOS) DESC, N.NOME LIMIT {{limit}} OFFSET {{offset}}